import*as THREE from'three';import{Component,Port,materials}from'../../core/index.js';import{roundedRect}from'../../core/geometry.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;
function board(host){const s=new THREE.Shape(),x=10.35,r=3.6,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);s.moveTo(-5.5,-10.4);s.lineTo(-8.7,-10.4);s.lineTo(-x,-8.8);s.lineTo(-x,-dy);s.absarc(-8,0,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,8.8);s.lineTo(-8.8,10.4);s.lineTo(8.8,10.4);s.lineTo(x,8.8);s.lineTo(x,dy);s.absarc(8,0,r,a,tau-a,false);s.lineTo(x,-8.8);s.lineTo(8.7,-10.4);s.lineTo(5.5,-10.4);s.lineTo(5.5,-5.5);s.lineTo(-5.5,-5.5);s.closePath();const bore=new THREE.Path();bore.absarc(0,0,1.8,0,tau,false);s.holes.push(bore);const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:48}),materials.plastic(0xe3e4d8,{roughness:.9}),[0,0,-1.2],'Mini PDM fixed PCB with mounting reliefs and central retaining bore');pcb.userData={role:'physical-pcb',inferred:true};const dark=materials.plastic(0x242820,{roughness:.8}),metal=materials.metal(0xaeb2a3,{roughness:.5}),ceramic=materials.plastic(0xb8a87e,{roughness:.88});const regulator=slab(host.body,1.3,2.9,.9,.09,[-5.6,5.4,-.4],dark,[],.01);regulator.name='Mini PDM U3 HT7333 fixed three-pin regulator';const leads=[];for(const[dx,dy]of[[-.85,-.95],[-.85,.95],[.85,0]])leads.push(mesh(host.body,new THREE.BoxGeometry(.65,.35,.16),metal,[-5.6+dx,5.4+dy,-.3],'Mini PDM HT7333 physical solder terminal'));
const passives=[];for(const[n,x,y,w,h]of[['C5 1uF',-5.7,8.5,1.6,.9],['C6 1uF',4.8,8.5,1.6,.9],['C7 100nF',4.8,6.5,1.2,.7]]){const p=slab(host.body,w,h,.55,.06,[x,y,-.4],ceramic,[],.01);p.name='Mini PDM fixed '+n;passives.push(p);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.2,h,.2),metal,[x+sign*(w/2-.07),y,-.27],'Mini PDM passive metal termination');}return{pcb,regulator,leads,passives};}
function microphone(host){const frame=new THREE.Group();frame.name='Mini PDM fixed SPM1423HM4H-B package installation';frame.position.fromArray(spec.sensor.position);host.body.add(frame);const metal=materials.metal(0x9ca4a2,{roughness:.49}),dark=materials.plastic(0x273326,{roughness:.87});const substrate=slab(frame,3.76,4.72,.22,.12,[0,0,0],dark,[],.01);substrate.name='Mini PDM real SPM1423 substrate and deep sound-port backing';const shape=roundedRect(3.76,4.72,.254),hole=new THREE.Path();hole.absarc(0,1.029,.42,0,tau,false);shape.holes.push(hole);const can=mesh(frame,new THREE.ExtrudeGeometry(shape,{depth:1.09,bevelEnabled:false,curveSegments:64}),metal,[0,0,.22],'Mini PDM metal MEMS can with true Ø0.840mm acoustic bore');can.userData={role:'physical-microphone-package',part:'SPM1423HM4H-B',packageMm:[3.76,4.72,1.31],acousticPortDiameterMm:.84,internalDepthInferred:true};const membrane=mesh(frame,new THREE.CylinderGeometry(.405,.405,.035,64).rotateX(Math.PI/2),materials.plastic(0x171c17,{roughness:.95}),[0,1.029,.245],'Mini PDM recessed non-emissive acoustic membrane appearance');membrane.userData={role:'passive-acoustic-backing',internalDepthInferred:true};const pads=[];for(const x of[-1.1685,1.1685])for(let i=0;i<3;i++){const y=1.649-i*1.651;const pad=mesh(frame,x>0&&i===0?new THREE.BoxGeometry(1.118,.711,.05):new THREE.CylinderGeometry(.457,.457,.05,32).rotateX(Math.PI/2),materials.metal(0xb8b096,{roughness:.44}),[x,y,-.015],'Mini PDM microphone fixed six-land termination '+(pads.length+1));pads.push(pad);}return{frame,substrate,can,membrane,pads};}
function grove(host){const frame=new THREE.Group();frame.name='Mini PDM physical white HY2.0-4P socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const white=materials.plastic(spec.grove.color,{roughness:.74}),metal=materials.metal(0xb7b6a3,{roughness:.42}),box=(s,p,n,m=white)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'Mini PDM Grove '+n),depth=6.1;
for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side rail');box([.7,.6,3.2],[sign*3.85,2.3,-4.5],'inner guide');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'locking shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'deep dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.3],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.3],[(i-1.5)*2,.2,-3.5],'real contact '+(i+1),metal));box([.42,1.3,.42],[(i-1.5)*2,-2.65,-5.6],'solder tail '+(i+1),metal);}const port=host.add(new Port({id:'grove',label:'PDM CLK/DAT · HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'DAT',color:'yellow'},{n:4,name:'CLK',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Four physical contacts and cable attachment/pose only;no PDM clock,audio,electrical,power or recording behavior'}}));return{frame,contacts,port};}
export function buildMiniPDM(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe7e8e1,{roughness:.8})}),pcb=board(host),sensor=microphone(host),input=grove(host),fixing=screw(host.body,[0,0,-3.84],'back',1.25);fixing.name='Mini PDM actual recessed central retaining screw';mesh(host.body,new THREE.CylinderGeometry(.6,.6,3.9,32).rotateX(Math.PI/2),materials.metal(0x9a9f95),[0,0,-1.85],'Mini PDM concealed fixed retaining screw shank');const front=mesh(host.body,new THREE.CylinderGeometry(2.5,2.5,.05,96).rotateX(Math.PI/2),materials.plastic(0xf1f2ec,{roughness:.86}),[0,0,4.025],'Mini PDM physical circular front adhesive substrate'),back=slab(host.body,16,4.2,.05,.08,[0,7.65,-3.85],materials.plastic(0xe0e3dc,{roughness:.87}),[],.005);back.name='Mini PDM physical rear pin-label adhesive substrate';front.userData={role:'physical-label-substrate',face:'front'};back.userData={role:'physical-label-substrate',face:'back'};const anchor=host.add(new Component({id:'sensor',label:'SPM1423 fixed acoustic appearance anchor',position:spec.sensor.acousticPortPosition,meta:{role:'visual-anchor',part:'SPM1423HM4H-B',outward:[0,0,1],scope:'Passive fixed acoustic aperture anchor only;no waveform,audio,recording,level,sampling,clock,PDM,value,register,electrical or firmware commands'}}));host.miniPdmAssembly={parts,pcb,sensor,input,fixing,labels:{front,back},anchor};host.unitStickers=addStickers(host);}
